import {needsEstablishedWater} from './water-service.js?v=adult-learning-1';
const zones=['residential','commercial','industrial'];
export function recoverySites(c){const sites=new Map();for(const t of c.tiles){if(t.fire)continue;let issue=null;if(t.radiation)issue={priority:0,label:'Contaminated land',action:'Relocate development; contamination cannot be cleared.',layer:'city'};else if(t.rubble)issue={priority:1,label:'Rubble',action:'Clear damage, then restore the site and its connections.',layer:'city'};else if(t.abandonedLevel)issue={priority:2,label:'Abandoned building',action:'Inspect the recorded cause and current recovery blockers.',layer:'zones'};else if(zones.includes(t.type)&&t.level){if(!t.powered)issue={priority:3,label:'Electricity interrupted',action:'Inspect the local electrical grid and restore supply.',layer:'power'};else if(needsEstablishedWater(t)&&!t.watered)issue={priority:4,label:'Water interrupted',action:'Restore pipes and enough supply on the local water network.',layer:'water'};}if(!issue)continue;const id=t.lotRoot??t.y*c.size+t.x,old=sites.get(id);if(!old||issue.priority<old.priority)sites.set(id,{...issue,x:t.x,y:t.y,id});}return [...sites.values()].sort((a,b)=>a.priority-b.priority||a.id-b.id);}
export function recoverySitesReport(c,page=0){const sites=recoverySites(c);page=Math.max(0,Math.min(page,Math.max(0,Math.ceil(sites.length/12)-1)));const start=page*12,shown=sites.slice(start,start+12);return `<details id="recoverySites" ${!c.emergency.active&&sites.length?'open':''}><summary>Recovery sites · ${sites.length} need attention</summary><p>Current damage and service problems, including any that preceded the emergency. Burning tiles remain in active emergency locations. Larger buildings appear once; this list does not advance time or spend funds.</p>${shown.length?`<ol start="${start+1}">${shown.map((s,i)=>`<li><strong>${s.label} · Tile ${s.x+1}, ${s.y+1}</strong><p>${s.action}</p><button data-recovery-site="${start+i}">Inspect site</button></li>`).join('')}</ol><p>Showing ${start+1}–${start+shown.length} of ${sites.length} sites, ordered by contamination, rubble, abandonment and utility interruptions. Repairing a site refreshes the list.</p><div class="actions">${page>0?`<button data-recovery-page="${page-1}">Previous sites</button>`:''}${start+12<sites.length?`<button data-recovery-page="${page+1}">Next sites</button>`:''}</div>`:'<p>No rubble, contamination, abandoned buildings or occupied zones with interrupted required utilities were found. Check roads and other infrastructure before expanding.</p>'}</details>`;}
export function installRecoverySites(c,inspect,root=document){const sites=recoverySites(c);root.querySelectorAll('[data-recovery-site]').forEach(button=>button.onclick=()=>{const site=sites[Number(button.dataset.recoverySite)];if(site)inspect({x:site.x,y:site.y},site.layer);});root.querySelectorAll('[data-recovery-page]').forEach(button=>button.onclick=()=>{root.querySelector('#recoverySites').outerHTML=recoverySitesReport(c,Number(button.dataset.recoveryPage));installRecoverySites(c,inspect,root);const panel=root.querySelector('#recoverySites');panel.open=true;panel.querySelector('summary').focus();});}
